const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={designs:[['Classic distinction','Recognition','classic'],['The academic','Academic','navy'],['Botanical grace','Workshop','sage'],['Modern achievement','Recognition','modern'],['A touch of warmth','Workshop','rose'],['Evening honors','Academic','dark']].map((d,i)=>({id:'d'+i,name:d[0],folder:d[1],style:d[2],date:'13 Oct 2026',nameY:49,idY:93})),people:[{id:'FOL-2026-001',name:'Amelia Bennett',email:'amelia@example.com',event:'Creative Leadership Workshop'},{id:'FOL-2026-002',name:'Daniel Lee',email:'daniel@example.com',event:'Creative Leadership Workshop'},{id:'FOL-2026-003',name:'Sofia Chen',email:'sofia@example.com',event:'Creative Leadership Workshop'}],folders:['Workshop','Academic','Recognition'],printed:0};
let state;try{state=JSON.parse(localStorage.getItem('folio-v1'))||initial}catch{state=initial}let tab='designs',folder='All designs',query='',selected=state.designs[0]?.id;
function save(){try{localStorage.setItem('folio-v1',JSON.stringify(state));$('#savestatus').textContent='Saved on this browser'}catch{$('#savestatus').textContent='Changes could not be saved';toast('Storage is full. Use a smaller image or export a backup.')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function certificate(d,p={name:'Alexandra Morgan',id:'FOL-2026-001',event:'Creative Leadership Workshop'}){if(d.image)return `<div class="cert" style="padding:0;border:0;background:white"><img alt="" src="${d.image}" style="position:absolute;inset:0;width:100%;height:100%;object-fit:fill"><div class="name" style="position:absolute;top:${d.nameY}%;left:5%;width:90%;margin:0;transform:translateY(-50%);color:#24352d">${esc(p.name)}</div><div class="identifier" style="bottom:auto;top:${d.idY}%;color:#24352d">${esc(p.id)}</div></div>`;return `<div class="cert ${esc(d.style)}"><div class="crest">✧</div><h2>CERTIFICATE</h2><div class="sub">OF PARTICIPATION</div><div class="presented">This certificate is proudly presented to</div><div class="name">${esc(p.name)}</div><div class="description">For participation in ${esc(p.event)}<br>In recognition of your dedication and commitment to learning.</div><div class="signatures"><span>──────────<br>Program Director</span><span>✦</span><span>──────────<br>Organizing Committee</span></div><div class="identifier">CERTIFICATE ID · ${esc(p.id)}</div></div>`}
function show(){document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});let titles={designs:['Design library','Choose a certificate that fits the occasion.'],participants:['Participants','Manage names, events, and unique certificate identifiers.'],print:['Print certificates','Preview your design, then print individually or in a batch.'],overview:['Your certificate workspace','Everything you need to recognize your participants.']};$('#title').textContent=titles[tab][0];$('#subtitle').textContent=titles[tab][1];$('#crumb').textContent=titles[tab][0];$('#newdesign').textContent=tab==='participants'?'＋ Add participant':'＋ Upload design';$('#stats').innerHTML=[['Certificate designs',state.designs.length,'▧'],['Participants',state.people.length,'♧'],['Prints prepared',state.printed,'⎙']].map(d=>`<div class="stat"><div><small>${d[0]}</small><strong>${d[1]}</strong></div><div class="icon">${d[2]}</div></div>`).join('');$('#navcount').textContent=state.designs.length;$('.toolbar').style.display=tab==='designs'||tab==='participants'?'flex':'none';$('.tabs').style.display=tab==='designs'?'flex':'none';$('#search').placeholder=tab==='participants'?'⌕  Search participants…':'⌕  Search designs…';$('.tabs').innerHTML=['All designs',...state.folders].map(f=>`<button data-folder="${esc(f)}" class="${folder===f?'selected':''}">${esc(f)} ${f==='All designs'?'<span>'+state.designs.length+'</span>':''}</button>`).join('')+'<button id="newfolder">＋ New folder</button>';
if(tab==='designs'){let ds=state.designs.filter(d=>(folder==='All designs'||d.folder===folder)&&d.name.toLowerCase().includes(query));$('#body').innerHTML=(ds.length?'':'<div class="empty"><h2>No designs in this view</h2><p>Try a different folder or search, or upload a certificate background.</p></div>')+'<div class="grid">'+ds.map(d=>`<article class="card"><button class="thumb" data-preview="${d.id}" aria-label="Preview ${esc(d.name)}">${certificate(d)}</button><div class="meta"><h3>${esc(d.name)}</h3><div class="row"><span class="badge">${esc(d.folder)}</span><span>${esc(d.date)}</span><button class="more" data-edit="${d.id}" aria-label="Edit ${esc(d.name)}">Edit</button></div></div></article>`).join('')+'<button class="uploadcard" id="uploadcard"><i>＋</i><strong>Upload a design</strong><span>Upload a certificate background</span><span style="margin-top:9px">PNG, JPG or WebP · up to 3 MB</span></button></div>';}
if(tab==='participants'){$('#body').innerHTML=`<div class="actions"><button class="secondary" id="importcsv">↑ Import CSV</button><button class="secondary" id="exportcsv">↓ Export CSV</button><button class="secondary" id="backup">Export workspace backup</button></div><p class="note">CSV columns: name, email, event, id (optional). Certificate IDs must be unique.</p><div class="tablewrap"><table><thead><tr><th>Participant</th><th>Email</th><th>Event</th><th>Certificate ID</th><th>Actions</th></tr></thead><tbody>${state.people.filter(p=>(p.name+' '+p.id+' '+p.email).toLowerCase().includes(query)).map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.email)}</td><td>${esc(p.event)}</td><td><span class="badge">${esc(p.id)}</span></td><td><button data-person="${esc(p.id)}">Edit</button> <button data-printone="${esc(p.id)}">Print</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching participants. Add a participant or import a CSV to begin.</td></tr>'}</tbody></table></div>`;}
if(tab==='print'){$('#body').innerHTML=`<div class="settinggrid"><div class="panel"><h3>Prepare your certificates</h3><label>Certificate design<select id="designselect">${state.designs.map(d=>`<option value="${d.id}" ${d.id===selected?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label>Preview participant<select id="personselect">${state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><p class="note">A4 landscape · one certificate per page. Choose “Save as PDF” in the print dialog to download. Enable background graphics for best results.</p><button class="primary" id="batch" ${!state.people.length||!state.designs.length?'disabled':''}>⎙ Print all ${state.people.length} certificates</button><button class="secondary" id="printcurrent" ${!state.people.length||!state.designs.length?'disabled':''}>Print selected participant</button><p class="note">Each certificate includes the corresponding participant’s unique ID.</p></div><div class="previewpane"><div class="previewlabel"><span>Certificate preview</span><span>A4 landscape</span></div><div class="preview" id="livepreview"></div><p class="note">The name and certificate ID match the selected participant.</p></div></div>`;updatePreview();}if(tab==='overview'){$('#body').innerHTML=`<h2 class="overviewintro">From design to printed certificate</h2><div class="stepguide"><button data-tab="designs"><small>Step 1</small><h2>Choose a design</h2><p>Explore six built-in styles or upload your own background. Organize designs into folders.</p></button><button data-tab="participants"><small>Step 2</small><h2>Add your participants</h2><p>Enter people individually or import a CSV. Every participant gets a unique certificate ID.</p></button><button data-tab="print"><small>Step 3</small><h2>Preview and print</h2><p>Match your design to each participant, then print or save as PDF from your browser.</p></button></div><div class="workspacehelp"><h3>Your workspace stays on this device</h3><p>Designs and participant records are saved in this browser. Export a backup from Participants before clearing browser data or changing devices.</p></div>`;}}
function updatePreview(){let d=state.designs.find(d=>d.id===$('#designselect')?.value);let p=state.people.find(p=>p.id===$('#personselect')?.value);$('#livepreview').innerHTML=d&&p?certificate(d,p):'<p>Add a design and a participant to preview.</p>'}
function modal(html,submit){$('#form').innerHTML=html;$('#dialog').showModal();$('#form').onsubmit=e=>{e.preventDefault();submit(new FormData($('#form')))}}const controls='<div class="actions"><button type="button" class="secondary" onclick="document.querySelector(\'#dialog\').close()">Cancel</button><button class="primary">Save</button></div>';
function person(id){let p=state.people.find(p=>p.id===id)||{name:'',email:'',event:'',id:nextId()};modal(`<h2 id="dialogtitle">${id?'Edit':'Add'} participant</h2>${['name','email','event','id'].map(k=>`<label>${({name:'Full name',email:'Email',event:'Event / program',id:'Certificate ID'})[k]}<input name="${k}" value="${esc(p[k])}" ${k==='name'||k==='id'?'required':''} ${k==='email'?'type="email"':''}></label>`).join('')}${id?'<button type="button" id="deleteperson" class="secondary">Delete participant</button>':''}${controls}`,f=>{let n=Object.fromEntries(f);for(let k in n)n[k]=n[k].trim();if(!n.name||!n.id)return;if(state.people.some(x=>x.id===n.id&&x!==p))return toast('That certificate ID already exists.');if(id)Object.assign(p,n);else state.people.push(n);save();$('#dialog').close();show()});if(id)$('#deleteperson').onclick=()=>{state.people=state.people.filter(x=>x!==p);save();$('#dialog').close();show()}}
function nextId(){let n=1;while(state.people.some(p=>p.id===`FOL-2026-${String(n).padStart(3,'0')}`))n++;return `FOL-2026-${String(n).padStart(3,'0')}`}
function editDesign(id,image){let d=state.designs.find(d=>d.id===id)||{id:crypto.randomUUID(),name:'Untitled design',folder:state.folders[0]||'General',style:'classic',image,nameY:49,idY:93,date:new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})};modal(`<h2 id="dialogtitle">${id?'Edit':'Upload'} design</h2><label>Design name<input name="name" value="${esc(d.name)}" required></label><label>Folder<select name="folder">${state.folders.map(f=>`<option ${f===d.folder?'selected':''}>${esc(f)}</option>`).join('')}</select></label>${d.image?`<p class="note">Use a blank certificate background. Overlay positions are measured from the top.</p><label>Name position (%)<input type="number" min="10" max="90" name="nameY" value="${d.nameY}"></label><label>Identifier position (%)<input type="number" min="5" max="98" name="idY" value="${d.idY}"></label>`:''}${id?'<button type="button" class="secondary" id="deletedesign">Delete design</button>':''}${controls}`,f=>{const values=Object.fromEntries(f);values.name=values.name.trim();if(!values.name)return toast('Enter a design name.');Object.assign(d,values);if(!id)state.designs.push(d);save();$('#dialog').close();show()});if(id)$('#deletedesign').onclick=()=>{state.designs=state.designs.filter(x=>x!==d);selected=state.designs[0]?.id;save();$('#dialog').close();show()}}
function printPeople(people){let d=state.designs.find(d=>d.id===selected)||state.designs[0];if(!d||!people.length)return toast('Add a design and participants first.');$('#printarea').innerHTML=people.map(p=>'<div class="printpage">'+certificate(d,p)+'</div>').join('');Promise.all([...$('#printarea').querySelectorAll('img')].map(i=>i.decode().catch(()=>{}))).then(()=>{window.print();state.printed+=people.length;save();show()})}
function download(name,content,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-preview]');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;query='';$('#search').value='';folder='All designs';show()}if(b.dataset.folder){folder=b.dataset.folder;show()}if(b.id==='newfolder')modal('<h2 id="dialogtitle">Create folder</h2><label>Folder name<input name="name" required maxlength="40"></label>'+controls,f=>{let n=f.get('name').trim();if(!n||state.folders.includes(n))return toast('Please use a new folder name.');state.folders.push(n);save();$('#dialog').close();show()});if(b.id==='newdesign'){if(tab==='participants')person();else $('#upload').click()}if(b.id==='uploadcard')$('#upload').click();if(b.dataset.edit)editDesign(b.dataset.edit);if(b.dataset.person)person(b.dataset.person);if(b.dataset.printone)printPeople(state.people.filter(p=>p.id===b.dataset.printone));if(b.dataset.preview){selected=b.dataset.preview;tab='print';show()}if(b.id==='printcurrent')printPeople(state.people.filter(p=>p.id===$('#personselect').value));if(b.id==='batch')printPeople(state.people);if(b.id==='importcsv')$('#csv').click();if(b.id==='backup')download('folio-backup.json',JSON.stringify(state,null,2),'application/json');if(b.id==='exportcsv')download('participants.csv',['name,email,event,id',...state.people.map(p=>['name','email','event','id'].map(k=>'"'+p[k].replaceAll('"','""')+'"').join(','))].join('\r\n'),'text/csv')});
$('#search').oninput=e=>{query=e.target.value.toLowerCase();show()};document.addEventListener('change',e=>{if(e.target.id==='designselect'){selected=e.target.value;updatePreview()}if(e.target.id==='personselect')updatePreview()});$('#upload').onchange=e=>{let f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3*1024*1024){toast('Choose a PNG, JPG or WebP under 3 MB.');e.target.value='';return}let r=new FileReader;r.onload=()=>editDesign(null,r.result);r.readAsDataURL(f);e.target.value=''};
function parseCSV(s){let rows=[],row=[],v='',quote=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(quote&&s[i+1]==='"'){v+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&s[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v=''}else v+=c}if(quote)throw Error('Unclosed quote');row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows}
$('#csv').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let rows=parseCSV((await f.text()).replace(/^\uFEFF/,'')),headers=rows.shift()?.map(x=>x.trim().toLowerCase());if(!headers?.includes('name'))throw Error('Include a name column.');let staged=[];let used=new Set(state.people.map(p=>p.id));rows.forEach((r,i)=>{let p=Object.fromEntries(headers.map((h,j)=>[h,(r[j]||'').trim()]));if(!p.name)throw Error('Missing name on row '+(i+2));if(!p.id){let n=1;do{p.id='FOL-2026-'+String(n++).padStart(3,'0')}while(used.has(p.id))}if(used.has(p.id))throw Error('Duplicate identifier: '+p.id);used.add(p.id);staged.push({name:p.name,email:p.email||'',event:p.event||'',id:p.id})});state.people.push(...staged);save();show();toast(staged.length+' participants imported.')}catch(err){toast('Import failed: '+err.message)}e.target.value=''};show();


